import java.util.*;
public class TextEditing{
    public static int maxLength(String s){
        StringBuilder t=new StringBuilder();
        boolean inside=false;
        for(int i=0;i<s.length();i++){
            char ch=s.charAt(i);
            if(ch=='(')
                inside=true;
            else if(ch==')'){
                inside=false;
                t.append('_');
            }
            if(!inside && ch!=')')
                t.append(ch);
        }
        String[] parts=t.toString().split("_");
        int max=0;
        for(String part:parts)
            max=Math.max(max, part.length());
        return max;
    }
    public static int count(String s){
        String[] arr=s.split("_");
        int count=0;
        for(String part:arr){
            if(!part.isEmpty())
                count++;
        }
        return count;
    }
    public static int words(String s){
        int total=0;
        StringBuilder t=new StringBuilder();
        boolean inside=false;
        for(int i=0;i<s.length();i++){
            char ch=s.charAt(i);
            if(ch=='(')
                inside=true;
            else if(ch==')'){
                inside=false;
                total+=count(t.toString());
                t.setLength(0);
            }
            if(inside && ch!='(')
                t.append(ch);
        }
        return total;
    }
    public static void main(String[] args) {
        Scanner sc=new Scanner(System.in);
        int n=sc.nextInt();
        String s=sc.next();
        System.out.println(maxLength(s)+" "+words(s));
    }
}
